/**
 * Personal theme songs: each player gets an original instrumental generated by ElevenLabs Music,
 * shaped by who they are in the game (top skill, streak, current island). Files live in
 * server/.data/music (gitignored); only the owner can stream theirs.
 */
import { SKILLS, type IslandTheme, type Skill } from '@last-voyage/game';
import type { Hono } from 'hono';
import { HTTPException } from 'hono/http-exception';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import type { Collections, UserDoc } from './db';
import { currentIsland } from './island';

const DIR = fileURLToPath(new URL('../.data/music/', import.meta.url));
const LENGTH_MS = 30_000;
const COOLDOWN_MS = 30_000;

const SKILL_SOUND: Record<Skill, string> = {
  grit: 'stomping boots and driving war drums, bold brass',
  charm: 'jaunty fiddle and hand claps, playful and charming',
  lore: 'mysterious harp and celesta, starlit and curious',
  craft: 'rhythmic woodblocks and hammered dulcimer, a workshop groove',
  seacraft: 'rolling accordion and creaking-rope percussion, wind in the sails',
};
const ISLAND_SOUND: Record<IslandTheme, string> = {
  tropical: 'steel drums and marimba, warm tropical breeze',
  spooky: 'minor key, music box and soft organ, playful-spooky',
  winter: 'sleigh bells and pizzicato strings, frosty sparkle',
  volcanic: 'taiko drums and low cello, rumbling heat',
};
const TEMPOS = ['slow and swaying', 'medium tempo', 'brisk', 'lively and fast'];
const KEYS = ['D minor', 'G major', 'A minor', 'C major', 'E minor', 'F major'];

function hash(s: string) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

/** Deterministic per player + version, so a remix gives a new variation. */
export function themePrompt(user: Pick<UserDoc, '_id' | 'skills' | 'streak'>, island: IslandTheme | null, version: number): string {
  const top = [...SKILLS].sort((a, b) => user.skills[b] - user.skills[a])[0]!;
  const h = hash(`${user._id.toHexString()}:${version}`);
  const mood = user.streak.calmDays >= 3 ? 'triumphant and proud' : 'hopeful and adventurous';
  return [
    'Original instrumental sea-adventure theme for a cozy cartoon pirate game, no vocals, no lyrics.',
    `Lead sound: ${SKILL_SOUND[top]}.`,
    island ? `Flavour: ${ISLAND_SOUND[island]}.` : '',
    `Mood: ${mood}. ${TEMPOS[h % TEMPOS.length]}, in ${KEYS[(h >> 3) % KEYS.length]}.`,
    'Catchy short motif that loops cleanly. Family friendly.',
  ]
    .filter(Boolean)
    .join(' ');
}

export function registerMusic(
  app: Hono<{ Variables: { user: UserDoc } }>,
  c: Collections,
  opts: { env: NodeJS.ProcessEnv; fetchImpl: typeof fetch },
) {
  const file = (u: UserDoc) => join(DIR, `${u._id.toHexString()}.mp3`);
  const view = (u: UserDoc) =>
    u.theme
      ? { status: u.theme.status, prompt: u.theme.prompt, version: u.theme.version, audio: u.theme.status === 'ready' ? `/me/theme/audio?v=${u.theme.version}` : null }
      : { status: 'none' as const, prompt: null, version: 0, audio: null };

  async function compose(user: UserDoc, version: number, prompt: string) {
    const key = opts.env.ELEVENLABS_API_KEY;
    try {
      if (!key) throw new Error('not configured');
      const res = await opts.fetchImpl('https://api.elevenlabs.io/v1/music?output_format=mp3_44100_128', {
        method: 'POST',
        headers: { 'xi-api-key': key, 'content-type': 'application/json', accept: 'audio/mpeg' },
        body: JSON.stringify({ prompt, music_length_ms: LENGTH_MS, model_id: 'music_v1' }),
        signal: AbortSignal.timeout(180_000),
      });
      if (!res.ok || !/audio/.test(res.headers.get('content-type') ?? '')) throw new Error(`music ${res.status}`);
      const bytes = new Uint8Array(await res.arrayBuffer());
      if (bytes.length < 1000 || bytes.length > 8_000_000) throw new Error('bad size');
      await mkdir(DIR, { recursive: true });
      const tmp = `${file(user)}.${version}.tmp`;
      await writeFile(tmp, bytes);
      await rename(tmp, file(user));
      await c.users.updateOne({ _id: user._id, 'theme.version': version }, { $set: { 'theme.status': 'ready', 'theme.updatedAt': new Date() } });
    } catch {
      await c.users.updateOne({ _id: user._id, 'theme.version': version }, { $set: { 'theme.status': 'failed', 'theme.updatedAt': new Date() } });
    }
  }

  app.get('/me/theme', async (ctx) => {
    const u = (await c.users.findOne({ _id: ctx.get('user')._id }))!;
    return ctx.json(view(u));
  });

  /** Start (or remix) the player's theme. Generation runs in the background; poll GET /me/theme. */
  app.post('/me/theme', async (ctx) => {
    const u = (await c.users.findOne({ _id: ctx.get('user')._id }))!;
    if (!opts.env.ELEVENLABS_API_KEY) throw new HTTPException(503, { message: 'music is not configured' });
    if (u.theme?.status === 'pending' && Date.now() - u.theme.updatedAt.getTime() < 200_000) return ctx.json(view(u));
    if (u.theme && Date.now() - u.theme.updatedAt.getTime() < COOLDOWN_MS) throw new HTTPException(429, { message: 'the band is tuning, try again in a moment' });
    const island = u.crewId ? (await currentIsland(c, u.crewId)).island.theme : null;
    const version = (u.theme?.version ?? 0) + 1;
    const prompt = themePrompt(u, island, version);
    const theme = { status: 'pending' as const, prompt, version, updatedAt: new Date() };
    await c.users.updateOne({ _id: u._id }, { $set: { theme } });
    void compose(u, version, prompt);
    return ctx.json(view({ ...u, theme }));
  });

  app.get('/me/theme/audio', async (ctx) => {
    const u = ctx.get('user');
    try {
      const bytes = await readFile(file(u));
      const body = new ArrayBuffer(bytes.byteLength);
      new Uint8Array(body).set(bytes);
      return new Response(body, { headers: { 'content-type': 'audio/mpeg', 'cache-control': 'private, max-age=3600', 'content-length': String(bytes.length) } });
    } catch {
      throw new HTTPException(404, { message: 'no theme yet' });
    }
  });
}
